#include "research_companies_page.hpp"
#include "industry_page.hpp"
#include <QtWidgets>
#include <iostream>
void need(bool b,const char* m){if(!b)throw std::runtime_error(m);}
int main(int argc,char** argv){QApplication app(argc,argv);try{QTemporaryDir d;auto store=std::make_shared<BusinessStore>(d.filePath("business.sqlite"));auto topic=store->save("topics",{{"name","测试主题"}});auto doc=store->save("docs",{{"title","测试原文"},{"text","测试公司（600001，上交所）生产设备"}});auto relation=store->save("relations",{{"topicId",topic["id"]},{"documentId",doc["id"]},{"stage","equipment"},{"claim","生产设备"},{"quote","生产设备"},{"polarity","supports"},{"verification","manuallyVerified"}});QString key=relation["id"].toString();
 {ResearchCompaniesPage page(store);auto table=page.findChild<QTableWidget*>("researchCompanyTable");need(table->rowCount()==1,"current company row");table->cellClicked(0,0);auto name=page.findChild<QLineEdit*>("companyName"),product=page.findChild<QLineEdit*>("companyProduct"),search=page.findChild<QLineEdit*>("companySearch");name->setText("测试公司");product->setText("未保存产品");search->setText("公司");need(product->text()=="未保存产品","filter overwrote draft");search->setText("不匹配");search->clear();table->cellClicked(0,0);need(product->text()=="未保存产品","hidden row lost draft");page.findChild<QPushButton*>("companyReload")->click();need(product->text()=="未保存产品","reload overwrote draft");auto state=page.saveState();ResearchCompaniesPage rebuilt(store);rebuilt.restoreState(state);need(rebuilt.findChild<QLineEdit*>("companyProduct")->text()=="未保存产品","rebuild lost draft");need(!store->read("relations")[0].toObject().contains("product"),"draft auto saved to relation");}
 {ResearchCompaniesPage page(store);need(page.findChild<QLineEdit*>("companyProduct")->text()=="未保存产品","close reopen lost draft");auto latest=relation;latest["claim"]="其他页面更改";store->save("relations",latest);page.findChild<QPushButton*>("companyReload")->click();page.findChild<QPushButton*>("companySave")->click();need(page.findChild<QLabel*>("companyState")->text().contains("已变化"),"stale draft overwrote new relation");page.findChild<QPushButton*>("companyDiscard")->click();need(page.findChild<QLineEdit*>("companyProduct")->text().isEmpty(),"explicit discard failed");page.findChild<QLineEdit*>("companyName")->setText("测试公司");page.findChild<QLineEdit*>("companyProduct")->setText("设备");page.findChild<QLineEdit*>("companyInstrument")->setText("SH:stock:600001");page.findChild<QPlainTextEdit*>("companyIdentityQuote")->setPlainText("测试公司（600001，上交所）");page.findChild<QPushButton*>("companySave")->click();auto saved=store->read("relations")[0].toObject();need(saved["company"].toObject()["instrumentId"]=="SH:stock:600001",page.findChild<QLabel*>("companyState")->text().toStdString().c_str());need(saved["verification"]=="manuallyVerified"&&saved["quote"]=="生产设备","manual/original changed");}
 std::unique_ptr<QWidget> host(industryPage(store,nullptr));auto tabs=qobject_cast<QTabWidget*>(host.get());need(tabs&&tabs->count()==2&&host->findChild<QWidget*>("researchCompaniesPage"),"legacy industry factory integration");std::cout<<"research page: selection, filter/reload/hidden/rebuild/reopen drafts, stale-save reject, discard, identity save and factory GREEN\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
